// The rule bits as readrules has them, and its extra rules.
struct Bits
{
    unsigned char *r;
    unsigned char er[4];
    bool get(int n) const { return (r[n >> 3] >> (n & 7)) & 1; }
    void set(int n, int v) { if(v) r[n >> 3] |= (unsigned char)(1 << (n & 7)); else r[n >> 3] &= (unsigned char)~(1 << (n & 7)); }
    void dep(int, int) {}       // readrules' copy of the stored bits (not rules)
    void clear_er() { er[0] = er[1] = er[2] = er[3] = 0; }
    void set_er(int n, int v) { if(v) er[n >> 3] |= (unsigned char)(1 << (n & 7)); else er[n >> 3] &= (unsigned char)~(1 << (n & 7)); }
};

struct Head
{
    const ZqRuleQuest &q;
    int zelda_version, build, version_major, compat, s_version;
    explicit Head(const ZqRuleQuest &q) : q(q), zelda_version(q.zelda_version), build(q.build), version_major(q.major),
                                          compat((int)q.compat), s_version(q.s_version) {}
    int compare(int a, int b, int c) const
    {
        if(q.major != a) return q.major < a ? -1 : 1;
        if(q.minor != b) return q.minor < b ? -1 : 1;
        if(q.patch != c) return q.patch < c ? -1 : 1;
        return 0;
    }
    bool title_starts(const char *s) const { return strncmp(q.title ? q.title : "", s, strlen(s)) == 0; }
    int author_cmp(const char *s) const { return strcmp(q.author ? q.author : "", s); }
};

