void zq_rules_upstream(bool is30, unsigned char *rules, const ZqRuleQuest &q)
{
    Bits R;
    R.r = rules;
    R.clear_er();
    const Head H(q);

    if(is30)
        updates30(R, H);
    else
        updates255(R, H);
}

unsigned long zq_rules_latest_compat(bool is30)
{
    return is30 ? 122UL : 65UL;
}

int zq_rule_count(bool is30)
{
    return is30 ? (int)(sizeof(g_rules30) / sizeof(g_rules30[0])) : (int)(sizeof(g_rules255) / sizeof(g_rules255[0]));
}

const ZqRuleInfo &zq_rule_at(bool is30, int k)
{
    return is30 ? g_rules30[k] : g_rules255[k];
}

const char *zq_rule_category(bool is30, int cat)
{
    if(cat < 0 || cat >= ZQ_RULE_CATEGORIES)
        return "??";

    return is30 ? g_cat30[cat] : g_cat255[cat];
}

int zq_rule_max(bool is30)
{
    return is30 ? 694 : 690;
}
